# Try spatial mapping without background values
def map_6to4_sampling_filtered(grid):
    result_flat = []

    for r_out in range(4):
        for c_out in range(4):
            r_in_min = int(r_out * 6 / 4)
            r_in_max = int((r_out + 1) * 6 / 4)
            c_in_min = int(c_out * 6 / 4)
            c_in_max = int((c_out + 1) * 6 / 4)

            # Sample center
            r_in_center = (r_in_max - r_in_min) // 2 + r_in_min
            c_in_center = (c_in_max - c_in_min) // 2 + c_in_min

            if 0 <= r_in_center < 6 and 0 <= c_in_center < 6:
                val = grid[r_in_center][c_in_center]
                if val != 3:
                    result_flat.append(val)

    # Try to arrange into 4x4 if possible
    if len(result_flat) == 16:
        return [result_flat[i*4:(i+1)*4] for i in range(4)]
    return result_flat[:16]

sampled = map_6to4_sampling_filtered(grid)
print(f"Sampled filtered: {sampled}")
if len(sampled) == 16:
    print(json.dumps({"action": "submit", "grid": sampled}))
else:
    print(f"Not 16 cells, got {len(sampled)}")

